<template><section class="metric-view" role="region" :aria-label="view.title"><component :is="compact ? 'h3' : 'h2'">{{ view.title }}</component><p v-if="!view.series.length" class="form-help">此视图暂无采样数据。</p><div v-for="(series, index) in view.series" :key="series.label + index" class="metric-series"><h3 v-if="series.label">{{ series.label }}</h3><p class="form-help">缺失采样显示为断点，表格中标记为无数据。</p><svg v-if="series.points.some(point => point.value !== null)" class="metric-chart" viewBox="0 0 320 110" role="img" :aria-label="view.title + (series.label ? ' · ' + series.label : '') + '趋势，缺失采样以断点显示'"><line x1="8" y1="103" x2="312" y2="103" class="metric-axis" /><g v-for="(segment, part) in metricSegments(series.points)" :key="part"><polyline v-if="segment.length > 1" :points="segment.map(point => point.x + ',' + point.y).join(' ')" /><circle v-for="(point, sample) in segment" :key="sample" :cx="point.x" :cy="point.y" r="2" /></g></svg><p v-else class="feedback">当前时间范围暂无有效采样。</p><div class="metric-table-scroll" tabindex="0" :aria-label="view.title + '数据表滚动区'"><table><caption>{{ view.title }}{{ series.label ? ' · ' + series.label : '' }} · {{ compact ? '最近采样' : '数据表' }}</caption><thead><tr><th scope="col">采样时间</th><th scope="col">数值</th></tr></thead><tbody><tr v-for="point in compact ? series.points.slice(-8) : series.points" :key="point.at"><th scope="row"><time :datetime="point.at">{{ formatTime(point.at) }}</time></th><td>{{ metricText(point.value, view.unit) }}</td></tr></tbody></table></div></div></section></template>
